"""Reference decodes for internal/codec TestColourMatchesReference (WP-105).

lab8-ref.png, lab16-ref.png: the samples of fixtures/tiff/lab8.tif and
lab16.tif converted colorimetrically as CIE L*a*b* relative to D50 (TIFF's
CIELab default) to sRGB: XYZ D50, Bradford to D65, IEC 61966-2-1.
dds-*-pillow.png: Pillow's DDS decoder on the fixtures/dds BCn textures.
jxl-cmyk-lcms.png: the CMYK samples of fixtures/jxl/cmyk.jxl (regenerated with
`go run ./testdata/gen cmyk-raw`) through its naive CMYK profile with lcms.

    python3 -m venv /tmp/v && /tmp/v/bin/pip install pillow numpy
    /tmp/v/bin/python testdata/golden/codec/reference.py

Last run with Pillow 12.3.0 and NumPy 2.5.3.
"""
import os
import numpy as np
from PIL import Image
R = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', '..'))
F = R + '/testdata/fixtures'
G = R + '/testdata/golden/codec'
os.makedirs(G, exist_ok=True)


def lab_to_srgb(L, a, b):
    """CIE L*a*b* (D50) -> XYZ D50 -> Bradford -> XYZ D65 -> sRGB (IEC 61966-2-1)."""
    def finv(t):
        return np.where(t > 6 / 29, t ** 3, 3 * (6 / 29) ** 2 * (t - 4 / 29))
    fy = (L + 16) / 116
    fx, fz = fy + a / 500, fy - b / 200
    xyz = np.stack([finv(fx) * 0.96422, finv(fy), finv(fz) * 0.82521], -1)
    B = np.array([[0.9555766, -0.0230393, 0.0631636], [-0.0282895, 1.0099416, 0.0210077], [0.0122982, -0.0204830, 1.3299098]])
    M = np.array([[3.2404542, -1.5371385, -0.4985314], [-0.9692660, 1.8760108, 0.0415560], [0.0556434, -0.2040259, 1.0572252]])
    c = np.clip(xyz @ B.T @ M.T, 0, 1)
    c = np.where(c <= 0.0031308, 12.92 * c, 1.055 * c ** (1 / 2.4) - 0.055)
    return np.round(c * 255).astype(np.uint8)


w, h = 64, 48
raw = open(F + '/tiff/lab8.tif', 'rb').read()[8:8 + w * h * 3]
lab = np.frombuffer(raw, np.uint8).reshape(h, w, 3)
L = lab[..., 0].astype(float) * 100 / 255
a = lab[..., 1].astype(np.int8).astype(float)
b = lab[..., 2].astype(np.int8).astype(float)
Image.fromarray(lab_to_srgb(L, a, b)).save(G + '/lab8-ref.png')
raw = open(F + '/tiff/lab16.tif', 'rb').read()[8:8 + w * h * 6]
lab = np.frombuffer(raw, '<u2').reshape(h, w, 3)
L = lab[..., 0].astype(float) * 100 / 65535
a = lab[..., 1].astype(np.int16).astype(float) / 256
b = lab[..., 2].astype(np.int16).astype(float) / 256
Image.fromarray(lab_to_srgb(L, a, b)).save(G + '/lab16-ref.png')
# CMYK JPEG XL: the fixtures' lossless samples, regenerated by `gen cmyk-raw`,
# through their naive CMYK profile with lcms (relative colorimetric).
import io, subprocess, tempfile
from PIL import ImageCms
with tempfile.TemporaryDirectory() as tmp:
    subprocess.run(['go', 'run', './testdata/gen', 'cmyk-raw', str(w), str(h), 'opaque',
                    tmp + '/c.cmyk', tmp + '/c.icc'], cwd=R, check=True)
    cmyk = Image.frombytes('CMYK', (w, h), open(tmp + '/c.cmyk', 'rb').read())
    prof = ImageCms.ImageCmsProfile(io.BytesIO(open(tmp + '/c.icc', 'rb').read()))
    t = ImageCms.buildTransform(prof, ImageCms.createProfile('sRGB'), 'CMYK', 'RGB',
                                renderingIntent=ImageCms.Intent.RELATIVE_COLORIMETRIC)
    ImageCms.applyTransform(cmyk, t).save(G + '/jxl-cmyk-lcms.png')
for name, mode in [('bc1-dx10', 'RGB'), ('bc4', 'L'), ('bc7-alpha', 'RGBA')]:
    im = Image.open(F + '/dds/' + name + '.dds'); im.load()
    im.convert(mode).save(G + '/dds-' + name + '-pillow.png')
print(sorted(os.listdir(G)))
